input.sparql:
SELECT ?sensor ?zoneName ?tsid WHERE {
  ?sensor a brick:Air_Temperature_Sensor .
  ?sensor brick:hasLocation ?zone .
  ?zone rdfs:label ?zoneName .
  ?sensor ref:hasTimeseriesId ?tsid .
}

SELECT ?sensor ?zoneName ?tsid WHERE {
  ?sensor a brick:Zone_Air_Temperature_Sensor .
  ?sensor brick:hasLocation ?zone .
  ?zone rdfs:label ?zoneName .
  ?sensor ref:hasTimeseriesId ?tsid .
}

SELECT ?sensor ?zoneiri ?zonelabel ?tsid WHERE {
  ?sensor a brick:Air_Temperature_Sensor .
  ?sensor brick:hasLocation ?zoneiri .
  OPTIONAL { ?zoneiri rdfs:label ?zonelabel }
  OPTIONAL { ?sensor ref:hasTimeseriesId ?tsid }
}

SELECT ?sensor ?zoneiri ?zonelabel ?tsid WHERE {
  ?sensor a brick:Zone_Air_Temperature_Sensor .
  ?sensor brick:hasLocation ?zoneiri .
  OPTIONAL { ?zoneiri rdfs:label ?zonelabel }
  OPTIONAL { ?sensor ref:hasTimeseriesId ?tsid }
}

SELECT ?sensor ?zone ?zonelabel ?tsid WHERE {
  ?sensor a brick:Air_Temperature_Sensor .
  ?sensor ref:hasExternalReference ?tsref .
  ?tsref ref:hasTimeseriesId ?tsid .
  ?sensor brick:hasLocation ?zone .
  OPTIONAL { ?zone rdfs:label ?zonelabel }
}

